script:
var doc = Document;
// Goal: tell the user what the run found and prove what it changed.
// execute_script answers with three separate things: return_value (what the script
// returned, serialised), output (everything written to the console, including
// Revit's own chatter), and mutations (the NET change the run committed).

// 1. Return DATA, not elements. Project each element to the fields the answer
//    needs; a List of anonymous objects comes back as a JSON array. A returned
//    Element renders as a marker, "<Autodesk.Revit.DB.Level: no display form -- this
//    type neither overrides ToString() nor is one the connector serializes. ...>",
//    because the formatter only serialises JSON-shaped values and types with a
//    ToString of their own.
var levelsBefore = new System.Collections.Generic.List<object>();
foreach (var e in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  var lvl = (Autodesk.Revit.DB.Level)e;
  levelsBefore.Add(new { id = lvl.Id.Value, name = lvl.Name, elevation = lvl.Elevation });
}

// 2. Console output is a separate channel: progress notes and markers go here and
//    never mix into return_value.
System.Console.WriteLine("levels before: " + levelsBefore.Count);

// 3. Make one change. The mutations report is NET per element: a created-then-edited
//    element counts once as created; a created-then-deleted one counts as nothing;
//    an edit to a pre-existing element counts as modified; a block that threw and was
//    rolled back contributes nothing; a Settle(keep:false) document is left out.
var created = Connector.WithTransaction(doc, () => {
  var lvl = Autodesk.Revit.DB.Level.Create(doc, 33.0);
  lvl.Name = "How-to L33 " + System.DateTime.UtcNow.Ticks;  // unique name; still one "created", not created + modified
  var scratch = Autodesk.Revit.DB.Level.Create(doc, 34.0);
  doc.Delete(scratch.Id);            // nets to nothing
  return new { id = lvl.Id.Value, name = lvl.Name };
});

// 4. Read the report in the RESPONSE, not from the script: expect
//    mutations.net_created == 1, net_deleted == 0, by_category.Levels.net_created == 1
//    (regeneration may add net_modified on dependents). Categories are named at event
//    time; elements without a category land in "(uncategorized)"; `truncated` flags
//    a run too large to itemise. A read-only run carries no mutations block at all.
//    Use the report as the check that the run did what it says.

// 5. Return the projection: ids and names the user can act on, plus what to expect
//    in the report so the two can be compared.
return new {
  levelsBefore,
  created,
  expectedMutations = new { net_created = 1, net_deleted = 0, category = "Levels" }
};
